import CoreGraphics

/// An sRGB color with opacity, components 0…1.
struct RGBA: Sendable, Hashable {
    let red: Double
    let green: Double
    let blue: Double
    let opacity: Double

    init(hex: UInt32, opacity: Double = 1) {
        red = Double((hex >> 16) & 0xFF) / 255
        green = Double((hex >> 8) & 0xFF) / 255
        blue = Double(hex & 0xFF) / 255
        self.opacity = opacity
    }
}

/// A color in the light and the dark theme.
struct ThemeColor: Sendable, Hashable {
    let light: RGBA
    let dark: RGBA
}

/// One layer of a CSS-style box shadow (a non-zero `spread` with no blur draws a hairline ring).
struct ShadowLayer: Sendable, Hashable {
    let x: CGFloat
    let y: CGFloat
    let blur: CGFloat
    let spread: CGFloat
    let color: RGBA
}

struct ThemeShadow: Sendable, Hashable {
    let light: [ShadowLayer]
    let dark: [ShadowLayer]
}

/// The accent-dependent colors.
struct AccentPalette: Sendable, Hashable {
    /// Today, completion, progress, data.
    let accent: ThemeColor
    let accentHover: ThemeColor
    /// Accent as text (small labels only).
    let accentInk: ThemeColor
    /// Tinted backgrounds.
    let accentSoft: ThemeColor
    /// The unfilled part of an accent meter or bar.
    let accentTrack: ThemeColor
    /// Activity heatmap: one hue, more is darker.
    let heat1: ThemeColor
    let heat2: ThemeColor
    let heat3: ThemeColor
    let heat4: ThemeColor
}

/// The accent people can choose in Settings.
